/* The tables of M40 · Complaints and surveys. */

export const complaintCategories = defineTable(
  'complaint_categories',
  { module: 'M40', scope: 'org' },
  {
    ...baseColumns,
    /** "Teaching", "Fees", "Transport", "Bullying", "Staff conduct", "Suggestion" */
    name: text().notNull(),
    nameUr: text(),
    kind: enumText(complaintCategoryKinds).notNull().default('complaint'),
    /** the role that receives it at a branch */
    ownerRole: text().notNull(),
    /** goes to the principal only */
    isSensitive: boolean().notNull().default(false),
    acknowledgeHours: integer().notNull().default(24),
    resolveHours: integer().notNull().default(120),
    isActive: boolean().notNull().default(true),
  },
  (t) => [uniqueIndex('complaint_categories_name_uq').on(t.orgId, t.name).where(live(t))],
);

export const complaints = defineTable(
  'complaints',
  { module: 'M40', scope: 'branch', self: 'raisedBy', selfAccess: 'read' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** from the `complaint` sequence */
    complaintNo: text().notNull(),
    categoryId: uuid()
      .references((): AnyPgColumn => complaintCategories.id)
      .notNull(),
    subject: text().notNull(),
    description: text().notNull(),
    /** empty when taken by phone or in person from someone with no login */
    raisedBy: uuid().references((): AnyPgColumn => profiles.id),
    raiserKind: enumText(complaintRaiserKinds).notNull(),
    /** for a complaint with no login */
    raiserName: text(),
    raiserPhone: text(),
    /** the raiser's name is hidden from everyone handling it */
    isAnonymous: boolean().notNull().default(false),
    /** the child concerned */
    studentId: uuid().references((): AnyPgColumn => students.id),
    aboutStaffId: uuid().references((): AnyPgColumn => staff.id),
    channel: enumText(complaintChannels).notNull().default('portal'),
    priority: enumText(complaintPriorities).notNull().default('normal'),
    /** copied from the category, may be raised */
    isSensitive: boolean().notNull().default(false),
    status: enumText(complaintStatuses).notNull().default('open'),
    ownerStaffId: uuid().references((): AnyPgColumn => staff.id),
    escalationLevel: integer().notNull().default(0),
    acknowledgeBy: timestamptz().notNull(),
    resolveBy: timestamptz().notNull(),
    acknowledgedAt: timestamptz(),
    resolvedAt: timestamptz(),
    /** what the raiser is told */
    resolution: text(),
    satisfaction: integer(),
    /** the staff member who took it on someone's behalf */
    recordedBy: uuid().references((): AnyPgColumn => profiles.id),
  },
  (t) => [
    between('complaints', t.satisfaction, 1, 5),
    index('complaints_branch_status_resolve_by_idx').on(t.orgId, t.branchId, t.status, t.resolveBy),
    index('complaints_raised_by_idx').on(t.orgId, t.raisedBy),
  ],
);

export const complaintUpdates = defineTable(
  'complaint_updates',
  { module: 'M40', scope: 'branch', appendOnly: true, staff: 'append' },
  {
    ...appendColumns,
    branchId: branchIdColumn(),
    complaintId: uuid()
      .references((): AnyPgColumn => complaints.id)
      .notNull(),
    body: text(),
    authorId: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    /** an internal note is never shown to the raiser */
    isInternal: boolean().notNull().default(true),
    statusFrom: text(),
    statusTo: text(),
  },
);

export const surveys = defineTable(
  'surveys',
  { module: 'M40', scope: 'org' },
  {
    ...baseColumns,
    title: text().notNull(),
    titleUr: text(),
    intro: text(),
    kind: enumText(surveyKinds).notNull(),
    /** the same shape as a notice's */
    audience: jsonb().notNull(),
    branchIds: uuid().array().notNull(),
    isAnonymous: boolean().notNull().default(true),
    /** `student` lets a guardian answer once for each child */
    oneResponsePer: enumText(surveyOneResponsePers).notNull().default('person'),
    opensAt: timestamptz().notNull(),
    closesAt: timestamptz().notNull(),
    /** results for a group smaller than this are hidden */
    minGroupSize: integer().notNull().default(5),
    status: enumText(surveyStatuses).notNull().default('draft'),
    createdBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
  },
  (t) => [check('surveys_closes_at_after', sql`${t.closesAt} > ${t.opensAt}`)],
);

export const surveyQuestions = defineTable(
  'survey_questions',
  { module: 'M40', scope: 'org' },
  {
    ...baseColumns,
    surveyId: uuid()
      .references((): AnyPgColumn => surveys.id)
      .notNull(),
    sortOrder: integer().notNull(),
    sectionTitle: text(),
    type: enumText(surveyQuestionTypes).notNull(),
    text: text().notNull(),
    textUr: text(),
    /** `{ key, label, labelUr? }[]` for choice questions */
    options: jsonb().notNull().default([]),
    isRequired: boolean().notNull().default(true),
    /** repeats the question for each teacher of the respondent's child */
    about: enumText(surveyQuestionAbouts).notNull().default('none'),
  },
);

/** Who may answer. Created when the survey opens. */
export const surveyInvitations = defineTable(
  'survey_invitations',
  { module: 'M40', scope: 'org', self: 'userId' },
  {
    ...baseColumns,
    surveyId: uuid()
      .references((): AnyPgColumn => surveys.id)
      .notNull(),
    userId: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    /** set when answering per child */
    studentId: uuid().references((): AnyPgColumn => students.id),
    /** only the fact, never linked to a response when anonymous */
    answeredAt: timestamptz(),
  },
  (t) => [
    uniqueIndex('survey_invitations_survey_user_student_uq')
      .on(
        t.surveyId,
        t.userId,
        sql`coalesce(${t.studentId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
      )
      .where(live(t)),
  ],
);

export const surveyResponses = defineTable(
  'survey_responses',
  { module: 'M40', scope: 'org', staff: 'none' },
  {
    ...baseColumns,
    surveyId: uuid()
      .references((): AnyPgColumn => surveys.id)
      .notNull(),
    /** always empty when the survey is anonymous */
    respondentId: uuid().references((): AnyPgColumn => profiles.id),
    branchId: uuid()
      .references((): AnyPgColumn => branches.id)
      .notNull(),
    /** kept for grouping results */
    gradeId: uuid().references((): AnyPgColumn => grades.id),
    sectionId: uuid().references((): AnyPgColumn => sections.id),
    respondentKind: enumText(surveyResponseRespondentKinds).notNull(),
    /** rounded to the hour when anonymous */
    submittedAt: timestamptz().notNull(),
  },
);

export const surveyAnswers = defineTable(
  'survey_answers',
  { module: 'M40', scope: 'org', staff: 'none' },
  {
    ...baseColumns,
    responseId: uuid()
      .references((): AnyPgColumn => surveyResponses.id)
      .notNull(),
    questionId: uuid()
      .references((): AnyPgColumn => surveyQuestions.id)
      .notNull(),
    /** for teacher feedback */
    aboutStaffId: uuid().references((): AnyPgColumn => staff.id),
    valueNumber: decimal(4, 1),
    valueOptions: text().array(),
    valueText: text(),
  },
  (t) => [
    uniqueIndex('survey_answers_response_question_about_staff_uq')
      .on(
        t.responseId,
        t.questionId,
        sql`coalesce(${t.aboutStaffId}, '00000000-0000-0000-0000-000000000000'::uuid)`,
      )
      .where(live(t)),
  ],
);
